"use strict";

/* ---- celestial_shell.js ---- */
/* ==========================================================================
   CC shell — Celestial, standalone.

   Cam: "please do a standalone app for Cams Cards and call it
   celestial." The same real extraction Cortex and Chords already
   went through. CS.Store/CS.toast/CS.confirm below are adapted
   directly from Chords' own already-proven implementations —
   unchanged in behaviour, just pointed at celestial_app.py's own Api
   instead.

   Genuinely different from Chords' own shell: Chords only ever
   mounts ONE tool, so its own shell never needed a router at all.
   Celestial has real, separate pages (Tarot, Oracle, Lenormand,
   Astrology, Meditation, Journal) reached through the top
   nav's own dropdowns, so this shell owns a small, real router that
   Chords never needed.
   ========================================================================== */
window.CS = window.CS || {};

/* --------------------------------------------------------------------------
   CS.Store — talks to celestial_app.py's own Api.
   -------------------------------------------------------------------------- */
CS.Store = (() => {
  let api = null;   // window.pywebview.api once the bridge is up

  const ready = new Promise((resolve) => {
    if (window.pywebview && window.pywebview.api) {
      api = window.pywebview.api;
      resolve();
      return;
    }
    window.addEventListener("pywebviewready", () => {
      api = window.pywebview.api;
      resolve();
    });
    setTimeout(() => resolve(), 800);
  });

  const isDesktop = () => api !== null;

  return {
    ready,
    isDesktop,

    async readJSON(name) {
      await ready;
      return isDesktop() ? api.cards_read_json(name) : null;
    },
    async writeJSON(name, data) {
      await ready;
      return isDesktop() ? api.cards_write_json(name, data) : {ok: false};
    },
    /** data: URL for an image, full resolution — use this only where
        Cam actually looks at the picture (an open card's own big
        art, a deck's own cover in its detail view). */
    async imageURL(name) {
      await ready;
      return isDesktop() ? api.cards_image_url(name) : null;
    },
    /** A downscaled, cached copy — for any grid or shelf of many
        small images at once, anything scrolled past rather than
        looked at directly. */
    async thumbURL(name, maxEdge) {
      await ready;
      return isDesktop() ? api.cards_thumb_url(name, maxEdge) : null;
    },
    /* -- the guidebook, as a PDF (guidebook_pdf.py) ---------------------- */
    /** Builds the PDF in Python from the files on disk -- only the deck and
        the chosen cards cross the bridge -- asks where to save it, and opens
        it. {ok, path} | {cancelled} | {error}. */
    async exportGuidebookPdf(kind, deckId, cardIds, cover) {
      await ready;
      if (!isDesktop()) return {error: "Exporting runs in the desktop app."};
      if (typeof api.cards_export_guidebook_pdf !== "function") {
        return {error: "Exporting needs a newer build \u2014 restart NeuroNet."};
      }
      return api.cards_export_guidebook_pdf(kind, deckId, cardIds, !!cover);
    },
    async saveImage(name, dataUrl) {
      await ready;
      return isDesktop() ? api.cards_save_image(name, dataUrl) : null;
    },
    /** The real fix for "the file browser closes but no photo" — a
        native file dialog called from Python, copying the file
        directly on disk, rather than the browser-side <input
        type="file"> + FileReader path that relied on a detached
        input's own change event firing reliably. Returns {name} or
        {error}/{cancelled}. */
    async pickAndSaveImage(targetName) {
      await ready;
      return isDesktop() ? api.pick_and_save_image(targetName) : null;
    },
    /* -- the card photos library --------------------------------------- */
    async cardPhotosList() {
      await ready;
      return isDesktop() ? api.card_photos_list() : [];
    },
    async cardPhotoURL(relpath) {
      await ready;
      return isDesktop() ? api.card_photo_url(relpath) : null;
    },
    async cardPhotoThumbURL(relpath, maxEdge) {
      await ready;
      return isDesktop() ? api.card_photo_thumb_url(relpath, maxEdge) : null;
    },
    async importCardPhotos() {
      await ready;
      return isDesktop() ? api.import_card_photos() : null;
    },
    async assignCardPhoto(relpath, targetName) {
      await ready;
      return isDesktop() ? api.assign_card_photo(relpath, targetName) : null;
    },
    async setCardPhotoTags(relpath, tags) {
      await ready;
      return isDesktop() ? api.set_card_photo_tags(relpath, tags) : null;
    },
    async allCardPhotoTags() {
      await ready;
      return isDesktop() ? api.all_card_photo_tags() : [];
    },

    /* -- meditation media -------------------------------------------- */
    async meditationList() {
      await ready;
      return isDesktop() ? api.meditation_list() : [];
    },
    async meditationImport() {
      await ready;
      return isDesktop() ? api.meditation_import()
        : {cancelled: true};
    },
    async meditationMediaURL(name) {
      await ready;
      return isDesktop() ? api.meditation_media_url(name)
        : {error: "Meditation media only plays in the desktop app."};
    },
    async meditationRemove(name, deleteFile) {
      await ready;
      return isDesktop() ? api.meditation_remove(name, deleteFile)
        : {ok: false};
    },
  };
})();

/* --------------------------------------------------------------------------
   CS.toast / CS.confirm — the small, shared chrome every section's own
   dialogs depend on.
   -------------------------------------------------------------------------- */
CS.toast = (msg, kind = "ok") => {
  const box = document.getElementById("cs-toasts");
  const el = document.createElement("div");
  el.className = "toast " + kind;
  el.textContent = msg;
  box.appendChild(el);
  setTimeout(() => el.remove(), 4200);
};

CS.confirm = ({title, body, fine = "", yes = "Go ahead", danger = true}) => {
  return new Promise((resolve) => {
    const veil = document.getElementById("cs-confirm-veil");
    veil.innerHTML = `
      <div class="modal" role="alertdialog" aria-modal="true"
           aria-label="${title}">
        <h3></h3><p></p><p class="fine"></p>
        <div class="row">
          <button class="btn btn-quiet" data-act="no">Cancel</button>
          <button class="btn ${danger ? "btn-danger" : "btn-save"}"
                  data-act="yes"></button>
        </div>
      </div>`;
    veil.querySelector("h3").textContent = title;
    veil.querySelector("p").textContent = body || "";
    const fineEl = veil.querySelector(".fine");
    if (fine) fineEl.textContent = fine; else fineEl.remove();
    veil.querySelector("[data-act=yes]").textContent = yes;
    const close = (v) => {
      veil.classList.remove("open");
      veil.innerHTML = "";
      resolve(v);
    };
    veil.querySelector("[data-act=no]").onclick = () => close(false);
    veil.querySelector("[data-act=yes]").onclick = () => close(true);
    veil.onclick = (e) => { if (e.target === veil) close(false); };
    veil.classList.add("open");
  });
};

/* --------------------------------------------------------------------------
   CS.register / CS.route — a small, real router. Genuinely new
   compared to Chords' own shell: Chords only ever had one tool to
   mount, so it never needed to switch between several. Celestial's
   own top nav routes between real, separate pages, each registered
   the same way chords.js already registers itself with CS.register.
   -------------------------------------------------------------------------- */
CS.pages = {};
CS.register = (id, page) => { CS.pages[id] = page; };

let currentPageId = null;
let currentUnmount = null;

async function CCRoute(pageId) {
  const page = CS.pages[pageId];
  if (!page) {
    CS.toast(`"${pageId}" isn't ready yet.`, "error");
    return;
  }
  if (currentUnmount) {
    try { currentUnmount(); } catch (e) { /* best-effort */ }
    currentUnmount = null;
  }
  currentPageId = pageId;
  paintNavActive(pageId);
  const mountEl = document.getElementById("cs-app");
  mountEl.innerHTML = "";
  const result = await page.mount(mountEl);
  if (typeof result === "function") currentUnmount = result;
}
CS.route = CCRoute;
CS.currentPage = () => currentPageId;

function paintNavActive(pageId) {
  document.querySelectorAll("[data-nav-page]").forEach((el) => {
    el.classList.toggle("on", el.dataset.navPage === pageId);
  });
  // a dropdown parent (Divination, Mindfulness) reads as "on" too
  // when one of its own children is the active page, so the top-
  // level nav item itself shows where Cam actually is
  document.querySelectorAll("[data-nav-group]").forEach((el) => {
    const ids = (el.dataset.navGroup || "").split(",");
    el.classList.toggle("on", ids.includes(pageId));
  });
}

/* --------------------------------------------------------------------------
   Boot — the clock, the top nav's own dropdown wiring, and the
   first, real page.
   -------------------------------------------------------------------------- */
function paintClock() {
  const el = document.getElementById("cs-top-bar-clock");
  if (!el) return;
  el.textContent = new Date().toLocaleString(undefined, {
    weekday: "short", month: "short", day: "numeric",
    hour: "numeric", minute: "2-digit", second: "2-digit",
  });
}

function wireTopNav() {
  document.querySelectorAll("[data-nav-page]").forEach((el) => {
    el.addEventListener("click", (e) => {
      e.preventDefault();
      closeAllDropdowns();
      CS.route(el.dataset.navPage);
    });
  });
  document.querySelectorAll(".nav-dropdown-toggle").forEach((btn) => {
    btn.addEventListener("click", (e) => {
      e.stopPropagation();
      const dd = btn.closest(".nav-dropdown");
      const wasOpen = dd.classList.contains("open");
      closeAllDropdowns();
      if (!wasOpen) dd.classList.add("open");
    });
  });
  /* Celestial's top nav is gone here, and with it the
   document-wide click handler that closed its dropdowns --
   it would have fired on every NeuroNet click. */
}
function closeAllDropdowns() {
  document.querySelectorAll(".nav-dropdown.open").forEach((dd) =>
    dd.classList.remove("open"));
}

async function boot() {
  /* Celestial's own top bar (and its clock) isn't in NeuroNet: no element,
     no once-a-second timer (2026-10-05 -- it ticked all day for nothing). */
  if (document.getElementById("cs-top-bar-clock")) {
    paintClock();
    setInterval(paintClock, 1000);
  }
  wireTopNav();
  await CS.route("astrology");
}



